local BASE_URL="https://raw.githubusercontent.com/jdbrande/computercraft-autobuilder/main"
local modules,loaded={},{}
local require
require=function(name)
  if loaded[name]~=nil then return loaded[name] end
  assert(modules[name],"Missing bundled module: "..name)
  loaded[name]=modules[name](); return loaded[name]
end
modules["autobuilder.install.sha256"]=function()
-- SHA-256 using CC:Tweaked's built-in Lua 5.2 bit32 API. No external libraries.
local M={}
local K={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2}
function M.digest(input)
  assert(type(input)=='string','hash input must be bytes')
  assert(bit32,'CC:Tweaked bit32 API required')
  local bx,band,bnot,rr,rs=bit32.bxor,bit32.band,bit32.bnot,bit32.rrotate,bit32.rshift
  local function word(n) return string.char(rs(n,24)%256,rs(n,16)%256,rs(n,8)%256,n%256) end
  local length=#input
  local data=input..'\128'..string.rep('\0',(55-length)%64)..word(math.floor(length/536870912))..word((length*8)%4294967296)
  local h={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}
  for offset=1,#data,64 do
