    end
    local a,b,c,d,e,f,g,z=table.unpack(h)
    for i=0,63 do
      local t1=(z+bx(rr(e,6),rr(e,11),rr(e,25))+bx(band(e,f),band(bnot(e),g))+K[i+1]+w[i])%4294967296
      local t2=(bx(rr(a,2),rr(a,13),rr(a,22))+bx(band(a,b),band(a,c),band(b,c)))%4294967296
      z,g,f,e,d,c,b,a=g,f,e,(d+t1)%4294967296,c,b,a,(t1+t2)%4294967296
    end
    local v={a,b,c,d,e,f,g,z}; for i=1,8 do h[i]=(h[i]+v[i])%4294967296 end
  end
  local out={}; for i=1,8 do out[i]=string.format('%08x',h[i]) end
